function report(rows) {
  // rows: { orderId, customerId, orderTotal } repeated once per line item
  let revenue = 0;
  const customers = new Set();
  for (const r of rows) {
    revenue += r.orderTotal;        // adds the order total once PER LINE
    customers.add(r.customerId);
  }
  return { revenue, customers: customers.size };
}

