-- speed up the line-item grid: avoid joining orders + customers
ALTER TABLE order_items ADD COLUMN order_status text;
ALTER TABLE order_items ADD COLUMN customer_city text;

-- one-time backfill
UPDATE order_items oi
SET order_status = o.status,
    customer_city = c.city
FROM orders o
JOIN customers c ON c.id = o.customer_id
WHERE oi.order_id = o.id;

